              </p>
            </div>
            <dl class="meta-list" aria-label="Image details">
              <div class="meta-row">
                <dt>Collection</dt>
                <dd>${item.collection}</dd>
              </div>
              <div class="meta-row">
                <dt>File size</dt>
                <dd>${item.size}</dd>
              </div>
              <div class="meta-row">
                <dt>Added</dt>
                <dd>${item.date}</dd>
              </div>
            </dl>
            <div>
              <div class="actions" aria-label="Image actions">
                ${Button({ className: "button-secondary", children: "Download" })}
                ${Button({
