        justify-content: space-between;
        gap: 1rem;
        padding: 0.9rem 1rem;
        border: 1px solid var(--border);
        border-radius: var(--radius-md);
        background: var(--surface-muted);
      }

      .meta-row dt {
        color: var(--muted);
        font-size: 0.9rem;
      }

      .meta-row dd {
        margin: 0;
        font-weight: 700;
        text-align: right;
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
      }

      button {
        min-height: 2.75rem;
        border: 0;
        border-radius: 999px;
        padding: 0.78rem 1.15rem;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        transition:
          background 160ms ease,
          border-color 160ms ease,
          color 160ms ease,
          transform 160ms ease;
      }

      button:hover {
        transform: translateY(-1px);
      }

      button:focus-visible,
      a:focus-visible {
        outline: 3px solid #111827;
        outline-offset: 3px;
      }

      .button-secondary {
        border: 1px solid var(--border);
        background: var(--surface);
        color: var(--text);
      }

      .button-secondary:hover {
        border-color: #aab4c2;
        background: #f8fafc;
      }

      .trigger,
      .button-danger {
        background: var(--danger);
        color: #ffffff;
      }

      .trigger:hover,
      .button-danger:hover {
        background: var(--danger-hover);
      }

      .status-message {
        min-height: 1.5rem;
        margin: 0;
        color: var(--muted);
        font-size: 0.95rem;
      }

      dialog {
        width: min(92vw, 30rem);
        max-height: calc(100vh - 2rem);
        overflow: auto;
        border: 0;
        border-radius: var(--radius-lg);
        padding: 0;
        color: var(--text);
        background: var(--surface);
        box-shadow: var(--shadow);
      }

      dialog::backdrop {
        background: rgb(15 23 42 / 62%);
        backdrop-filter: blur(6px);
      }

      .dialog-content {
        padding: clamp(1.25rem, 5vw, 2rem);
      }

      .dialog-icon {
        display: grid;
        width: 3rem;
        height: 3rem;
        margin-bottom: 1rem;
        place-items: center;
        border-radius: 1rem;
        background: #fee2e2;
        color: var(--danger);
        font-size: 1.45rem;
        font-weight: 900;
      }

      .dialog-content h2 {
        margin: 0;
        font-size: clamp(1.55rem, 6vw, 2.2rem);
        line-height: 1.05;
        letter-spacing: -0.045em;
