      .dialog-content p {
        margin: 0.9rem 0 0;
        color: var(--muted);
        line-height: 1.65;
      }

      .dialog-actions {
        display: flex;
        justify-content: flex-end;
        gap: 0.75rem;
        margin-top: 1.5rem;
      }

      @media (max-width: 760px) {
        .site-header,
        .preview-card {
          grid-template-columns: 1fr;
        }

        .site-header {
          align-items: flex-start;
          flex-direction: column;
