        alt: "A calm lake bordered by pine trees and mountains at sunrise",
        collection: "Nordic Landscapes",
        size: "8.4 MB",
        date: "May 6, 2026",
      };

      const Button = ({ className = "", id = "", children, attributes = "" }) => `
        <button type="button" ${id ? `id="${id}"` : ""} class="${className}" ${attributes}>
          ${children}
        </button>
      `;

      const AppHeader = () => `
        <header class="site-header" aria-label="Library header">
          <div class="brand">
            <span class="brand-mark" aria-hidden="true">P</span>
            <span>Pixel Library</span>
          </div>
          <span class="header-pill">Image preview</span>
        </header>
      `;

      const ImagePreview = ({ item }) => `
        <article class="preview-card" aria-labelledby="page-title">
          <div class="image-panel">
            <img src="${item.src}" alt="${item.alt}" />
          </div>
          <div class="details-panel">
            <div>
              <p class="eyebrow">Saved image</p>
              <h1 id="page-title">${item.title}</h1>
              <p class="summary">
                Review this image before making changes to your library. Deleting it removes the image from this collection.
              </p>
            </div>
            <dl class="meta-list" aria-label="Image details">
              <div class="meta-row">
                <dt>Collection</dt>
                <dd>${item.collection}</dd>
              </div>
              <div class="meta-row">
                <dt>File size</dt>
                <dd>${item.size}</dd>
              </div>
              <div class="meta-row">
                <dt>Added</dt>
                <dd>${item.date}</dd>
              </div>
            </dl>
            <div>
              <div class="actions" aria-label="Image actions">
                ${Button({ className: "button-secondary", children: "Download" })}
                ${Button({
                  className: "trigger",
                  id: "delete-image-button",
                  children: "Delete image",
                  attributes: 'aria-haspopup="dialog" aria-controls="delete-dialog"',
                })}
              </div>
              <p id="delete-status" class="status-message" aria-live="polite"></p>
            </div>
          </div>
        </article>
      `;

      const DeleteDialog = ({ item }) => `
        <dialog id="delete-dialog" aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-description">
          <div class="dialog-content">
            <div class="dialog-icon" aria-hidden="true">!</div>
            <h2 id="delete-dialog-title">Delete this image?</h2>
            <p id="delete-dialog-description">
              "${item.title}" will be removed from your library. This action cannot be undone.
            </p>
            <div class="dialog-actions">
              ${Button({ className: "button-secondary", id: "cancel-delete", children: "Cancel" })}
              ${Button({ className: "button-danger", id: "confirm-delete", children: "Delete image" })}
            </div>
          </div>
        </dialog>
      `;

      const App = ({ item }) => `
        <div class="app-shell">
          ${AppHeader()}
          <main id="main-content">
            ${ImagePreview({ item })}
          </main>
        </div>
        ${DeleteDialog({ item })}
      `;

      document.getElementById("root").innerHTML = App({ item: image });

      const dialog = document.getElementById("delete-dialog");
      const trigger = document.getElementById("delete-image-button");
      const cancelButton = document.getElementById("cancel-delete");
      const confirmButton = document.getElementById("confirm-delete");
      const statusMessage = document.getElementById("delete-status");

      trigger.addEventListener("click", () => {
        dialog.showModal();
        cancelButton.focus();
      });

      cancelButton.addEventListener("click", () => {
        dialog.close("cancel");
      });

      confirmButton.addEventListener("click", () => {
        dialog.close("delete");
      });

      dialog.addEventListener("close", () => {
        if (dialog.returnValue === "delete") {
          statusMessage.textContent = "Image deleted from your library.";
        }
      });
    </script>
  </body>
