             <p id="delete-dialog-description">
               "${item.title}" will be removed from your library. This action cannot be undone.
             </p>
             <div class="dialog-actions">
               ${Button({ className: "button-secondary", id: "cancel-delete", children: "Cancel" })}
               ${Button({ className: "button-danger", id: "confirm-delete", children: "Delete image" })}
             </div>
           </div>
         </dialog>
       `;

       const App = ({ item }) => `
         <div class="app-shell">
           ${AppHeader()}
           <main id="main-content">
             ${ImagePreview({ item })}
           </main>
         </div>
         ${DeleteDialog({ item })}
       `;

       document.getElementById("root").innerHTML = App({ item: image });

       const dialog = document.getElementById("delete-dialog");
       const trigger = document.getElementById("delete-image-button");
       const cancelButton = document.getElementById("cancel-delete");
       const confirmButton = document.getElementById("confirm-delete");
       const statusMessage = document.getElementById("delete-status");

       trigger.addEventListener("click", () => {
         dialog.showModal();
         cancelButton.focus();
       });

       cancelButton.addEventListener("click", () => {
         dialog.close("cancel");
       });

       confirmButton.addEventListener("click", () => {
         dialog.close("delete");
       });

       dialog.addEventListener("close", () => {
         if (dialog.returnValue === "delete") {
           statusMessage.textContent = "Image deleted from your library.";
         }
       });
     </script>
   </body>
 </html>

')
